<script setup lang="ts">
import { Head, Link, router } from '@inertiajs/vue3';
import { ArrowLeft, Check, ChevronRight, Clock3, MapPin, Upload, Users, X } from '@lucide/vue';
import { computed, onMounted, ref, watch } from 'vue';

interface Rate { id: number; rental_type: string; price: string | number; }
interface Facility { id: number; name: string; }
interface Space { id: number; name: string; capacity: number | null; status: string; facilities: Facility[]; pricing_rates: Rate[]; }
interface Zone { id: number; name: string; pricing_model: string; is_online_bookable: boolean; zone_spaces: Space[]; }

const props = defineProps<{ zones: Zone[]; initial: { date?: string; zone_id?: string } }>();
const storageKey = 'sport-center-booking-draft';
const step = ref(new URLSearchParams(window.location.search).get('step') === '2' ? 2 : 1);
const selectedZoneId = ref<number | null>(props.zones[0]?.id ?? null);
const selectedSpaceId = ref<number | null>(null);
const bookingDate = ref('');
const selectedTime = ref('');
const guestName = ref('');
const paymentOption = ref<'full_payment' | 'half_payment' | 'pay_later'>('full_payment');
const paymentProof = ref<File | null>(null);
const paymentProofPreview = ref('');
const error = ref('');
const submitting = ref(false);

const selectedZone = computed(() => props.zones.find((zone) => zone.id === selectedZoneId.value));
const selectedSpace = computed(() => selectedZone.value?.zone_spaces.find((space) => space.id === selectedSpaceId.value));
const selectedRate = computed(() => selectedSpace.value?.pricing_rates?.[0]);
const totalAmount = computed(() => Number(selectedRate.value?.price ?? 0));
const amountToPay = computed(() => paymentOption.value === 'full_payment' ? totalAmount.value : paymentOption.value === 'half_payment' ? totalAmount.value / 2 : 0);
const today = new Date().toISOString().slice(0, 10);
const canContinue = computed(() => Boolean(selectedSpace.value && bookingDate.value && selectedTime.value));
const formatPrice = (price: number) => new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', maximumFractionDigits: 0 }).format(price);

const saveDraft = () => localStorage.setItem(storageKey, JSON.stringify({ zone_space_id: selectedSpaceId.value, zone_id: selectedZoneId.value, booking_date: bookingDate.value, start_time: selectedTime.value, zone_name: selectedZone.value?.name ?? '', space_name: selectedSpace.value?.name ?? '', rental_type: selectedRate.value?.rental_type ?? '', total_amount: totalAmount.value, guest_name: guestName.value, payment_option: paymentOption.value }));

onMounted(() => {
    try {
        const saved = JSON.parse(localStorage.getItem(storageKey) ?? 'null');
        if (saved) { selectedZoneId.value = saved.zone_id ?? selectedZoneId.value; selectedSpaceId.value = saved.zone_space_id ?? null; bookingDate.value = saved.booking_date ?? ''; selectedTime.value = saved.start_time ?? ''; guestName.value = saved.guest_name ?? ''; paymentOption.value = saved.payment_option ?? 'full_payment'; }
    } catch { localStorage.removeItem(storageKey); }
});
watch([selectedZoneId, selectedSpaceId, bookingDate, selectedTime, guestName, paymentOption], saveDraft);

const selectZone = (zone: Zone) => { selectedZoneId.value = zone.id; selectedSpaceId.value = null; };
const goPayment = () => { if (!canContinue.value) { error.value = 'Lengkapi area, space, tanggal, dan jam terlebih dahulu.'; return; } saveDraft(); step.value = 2; window.history.pushState({}, '', '/?step=2'); };
const backToBooking = () => { step.value = 1; window.history.pushState({}, '', '/'); };
const handleProofUpload = (event: Event) => { const file = (event.target as HTMLInputElement).files?.[0] ?? null; if (!file || !file.type.match(/^image\/(jpeg|png|webp)$/i)) { error.value = 'Bukti pembayaran harus berupa JPG, PNG, atau WebP.'; return; } if (file.size > 5 * 1024 * 1024) { error.value = 'Ukuran bukti pembayaran maksimal 5 MB.'; return; } paymentProof.value = file; paymentProofPreview.value = URL.createObjectURL(file); error.value = ''; };
const removeProof = () => { if (paymentProofPreview.value) URL.revokeObjectURL(paymentProofPreview.value); paymentProof.value = null; paymentProofPreview.value = ''; };
const submitBooking = () => { if (!selectedSpace.value || submitting.value) return; if (!guestName.value.trim()) { error.value = 'Nama lengkap wajib diisi.'; return; } if (paymentOption.value !== 'pay_later' && !paymentProof.value) { error.value = 'Upload bukti pembayaran terlebih dahulu.'; return; } submitting.value = true; error.value = ''; router.post('/booking', { zone_space_id: selectedSpaceId.value, guest_name: guestName.value.trim(), booking_date: bookingDate.value, start_time: selectedTime.value, payment_option: paymentOption.value, payment_proof: paymentProof.value }, { forceFormData: true, onError: (errors) => { error.value = Object.values(errors)[0] ?? 'Booking gagal dikirim. Silakan coba lagi.'; }, onSuccess: () => localStorage.removeItem(storageKey), onFinish: () => { submitting.value = false; } }); };
</script>

<template>
<Head :title="step === 2 ? 'Pembayaran Booking' : 'Online Booking'" />
<div class="min-h-screen bg-[#f7f8f6] text-slate-900">
<header class="sticky top-0 z-30 border-b border-white/60 bg-[#f7f8f6]/90 backdrop-blur-xl"><div class="mx-auto flex max-w-7xl items-center justify-between px-5 py-4 sm:px-8"><Link href="/" class="flex items-center gap-3"><div class="flex size-10 items-center justify-center rounded-2xl bg-slate-900 text-sm font-black text-white">SC</div><div><p class="text-sm font-bold">Sport Center</p><p class="text-[10px] font-medium uppercase tracking-[0.2em] text-slate-400">Play. Move. Connect.</p></div></Link><span class="rounded-full bg-slate-900 px-4 py-2 text-xs font-bold text-white">Step {{ step }} of 2</span></div></header>

<main v-if="step === 1"><section class="bg-slate-950 text-white"><div class="mx-auto max-w-7xl px-5 py-14 sm:px-8"><div class="mb-5 inline-flex items-center gap-2 rounded-full border border-white/15 bg-white/10 px-4 py-2 text-xs font-semibold"><span class="size-1.5 rounded-full bg-emerald-400"></span> Online booking is open</div><h1 class="max-w-3xl text-4xl font-black leading-[1.05] tracking-[-0.04em] sm:text-6xl">Book your<br /><span class="text-slate-400">game time.</span></h1><p class="mt-6 max-w-xl text-base leading-7 text-slate-300 sm:text-lg">Pilih fasilitas dan jadwal terlebih dahulu. Nama lengkap diisi pada langkah pembayaran.</p></div></section>
<section class="mx-auto max-w-7xl px-5 py-12 sm:px-8 lg:py-16"><div v-if="zones.length" class="grid gap-10 lg:grid-cols-[1fr_380px]"><div class="space-y-10">
<div><div class="mb-5"><p class="text-xs font-bold uppercase tracking-[0.2em] text-slate-400">Step 01</p><h2 class="mt-1 text-2xl font-black">Choose your area</h2></div><div class="grid gap-4 sm:grid-cols-3"><button v-for="zone in zones" :key="zone.id" type="button" class="rounded-3xl border bg-white p-5 text-left transition hover:shadow-lg" :class="selectedZoneId === zone.id ? 'border-slate-900 ring-2 ring-slate-900/10' : 'border-slate-200'" @click="selectZone(zone)"><div class="mb-6 flex items-center justify-between"><div class="flex size-11 items-center justify-center rounded-2xl bg-slate-100"><MapPin class="size-5" /></div><Check v-if="selectedZoneId === zone.id" class="size-5" /></div><p class="font-bold">{{ zone.name }}</p><p class="mt-1 text-xs text-slate-400">{{ zone.zone_spaces.length }} space tersedia</p></button></div></div>
<div v-if="selectedZone"><div class="mb-5"><p class="text-xs font-bold uppercase tracking-[0.2em] text-slate-400">Step 02</p><h2 class="mt-1 text-2xl font-black">Choose your space</h2></div><div class="grid gap-4 sm:grid-cols-2"><button v-for="space in selectedZone.zone_spaces" :key="space.id" type="button" class="rounded-3xl border bg-white p-6 text-left transition hover:shadow-lg" :class="selectedSpaceId === space.id ? 'border-slate-900 ring-2 ring-slate-900/10' : 'border-slate-200'" @click="selectedSpaceId = space.id"><div class="flex items-start justify-between"><div><p class="font-bold">{{ space.name }}</p><div class="mt-3 flex gap-3 text-xs text-slate-400"><span v-if="space.capacity" class="inline-flex items-center gap-1"><Users class="size-3.5" /> {{ space.capacity }} orang</span><span class="inline-flex items-center gap-1"><Clock3 class="size-3.5" /> Available</span></div></div><div class="flex size-7 items-center justify-center rounded-full border" :class="selectedSpaceId === space.id ? 'border-slate-900 bg-slate-900 text-white' : 'border-slate-200'"><Check v-if="selectedSpaceId === space.id" class="size-4" /></div></div><div v-if="space.facilities.length" class="mt-5 flex flex-wrap gap-1.5"><span v-for="facility in space.facilities" :key="facility.id" class="rounded-full bg-slate-100 px-3 py-1.5 text-[11px] text-slate-500">{{ facility.name }}</span></div></button></div></div>
<div><div class="mb-5"><p class="text-xs font-bold uppercase tracking-[0.2em] text-slate-400">Step 03</p><h2 class="mt-1 text-2xl font-black">Choose your schedule</h2></div><div class="grid gap-4 rounded-3xl border border-slate-200 bg-white p-5 sm:grid-cols-2"><label><span class="mb-2 block text-sm font-bold">Tanggal</span><input v-model="bookingDate" :min="today" type="date" class="w-full rounded-2xl border border-slate-200 bg-slate-50 px-4 py-3.5 text-sm outline-none focus:border-slate-900" /></label><label><span class="mb-2 block text-sm font-bold">Jam</span><input v-model="selectedTime" type="time" class="w-full rounded-2xl border border-slate-200 bg-slate-50 px-4 py-3.5 text-sm outline-none focus:border-slate-900" /></label></div></div><p v-if="error" class="rounded-2xl bg-red-50 p-4 text-sm font-semibold text-red-600">{{ error }}</p></div>
<aside class="lg:sticky lg:top-24 lg:self-start"><div class="rounded-[2rem] bg-slate-900 text-white shadow-2xl"><div class="p-7 sm:p-8"><p class="text-xs font-bold uppercase tracking-[0.2em] text-slate-500">Booking summary</p><h2 class="mt-2 text-2xl font-black">{{ selectedSpace?.name ?? 'Choose a space' }}</h2><div class="my-7 space-y-4 border-y border-white/10 py-6 text-sm"><div class="flex justify-between"><span class="text-slate-500">Area</span><span class="font-semibold">{{ selectedZone?.name ?? '—' }}</span></div><div class="flex justify-between"><span class="text-slate-500">Tanggal</span><span class="font-semibold">{{ bookingDate || '—' }}</span></div><div class="flex justify-between"><span class="text-slate-500">Jam</span><span class="font-semibold">{{ selectedTime || '—' }}</span></div></div><p class="text-xs uppercase tracking-widest text-slate-500">Total booking</p><p class="mt-1 text-3xl font-black">{{ formatPrice(totalAmount) }}</p><button type="button" :disabled="!canContinue" class="mt-7 flex w-full items-center justify-center gap-2 rounded-2xl bg-white px-5 py-4 text-sm font-bold text-slate-900" :class="!canContinue ? 'cursor-not-allowed opacity-40' : 'hover:bg-slate-100'" @click="goPayment">Lanjut ke Pembayaran <ChevronRight class="size-4" /></button></div></div></aside></div></section></main>

<main v-else class="mx-auto max-w-5xl px-5 py-10 sm:px-8 lg:py-14"><div class="grid gap-8 lg:grid-cols-[1fr_360px]"><div><button type="button" class="mb-6 inline-flex items-center gap-2 text-sm font-bold text-slate-500 hover:text-slate-900" @click="backToBooking"><ArrowLeft class="size-4" /> Kembali ke booking</button><div class="mb-7"><p class="text-xs font-bold uppercase tracking-[0.2em] text-slate-400">Step 2</p><h1 class="mt-1 text-3xl font-black sm:text-4xl">Data pemesan & pembayaran</h1></div><div class="space-y-5"><div class="rounded-3xl border border-slate-200 bg-white p-5 sm:p-7"><label><span class="mb-2 block text-sm font-bold">Nama lengkap</span><input v-model="guestName" type="text" autocomplete="name" placeholder="Masukkan nama lengkap" class="w-full rounded-2xl border border-slate-200 bg-slate-50 px-4 py-3.5 text-sm outline-none focus:border-slate-900" /></label></div><div class="rounded-3xl border border-slate-200 bg-white p-5 sm:p-7"><p class="text-sm font-bold">Metode pembayaran</p><div class="mt-4 grid gap-3 sm:grid-cols-3"><button type="button" class="rounded-2xl border p-4 text-left" :class="paymentOption === 'full_payment' ? 'border-slate-900 bg-slate-50' : 'border-slate-200'" @click="paymentOption = 'full_payment'"><b>Full payment</b><p class="mt-1 text-xs text-slate-500">Bayar 100%</p></button><button type="button" class="rounded-2xl border p-4 text-left" :class="paymentOption === 'half_payment' ? 'border-slate-900 bg-slate-50' : 'border-slate-200'" @click="paymentOption = 'half_payment'"><b>Half payment</b><p class="mt-1 text-xs text-slate-500">Bayar 50% / DP</p></button><button type="button" class="rounded-2xl border p-4 text-left" :class="paymentOption === 'pay_later' ? 'border-slate-900 bg-slate-50' : 'border-slate-200'" @click="paymentOption = 'pay_later'"><b>Bayar nanti</b><p class="mt-1 text-xs text-slate-500">Belum bayar</p></button></div><div v-if="paymentOption !== 'pay_later'" class="mt-6"><input id="payment-proof" type="file" accept="image/jpeg,image/png,image/webp" class="hidden" @change="handleProofUpload" /><label for="payment-proof" class="flex cursor-pointer flex-col items-center rounded-2xl border-2 border-dashed border-slate-300 bg-slate-50 p-8 text-center"><Upload class="size-7 text-slate-400" /><p class="mt-3 text-sm font-bold">Upload bukti pembayaran</p><p class="mt-1 text-xs text-slate-400">JPG, PNG, WebP • maksimal 5 MB</p></label><div v-if="paymentProofPreview" class="relative mt-4 overflow-hidden rounded-2xl border"><img :src="paymentProofPreview" alt="Bukti pembayaran" class="max-h-80 w-full object-contain" /><button type="button" class="absolute right-3 top-3 flex size-9 items-center justify-center rounded-full bg-white shadow" @click="removeProof"><X class="size-4" /></button></div></div><p v-if="error" class="mt-5 rounded-xl bg-red-50 p-3 text-xs font-semibold text-red-600">{{ error }}</p></div></div></div><aside class="lg:sticky lg:top-24 lg:self-start"><div class="rounded-[2rem] bg-slate-900 text-white shadow-2xl p-7 sm:p-8"><p class="text-xs font-bold uppercase tracking-[0.2em] text-slate-500">Booking summary</p><h2 class="mt-2 text-2xl font-black">{{ selectedSpace?.name }}</h2><div class="my-7 space-y-4 border-y border-white/10 py-6 text-sm"><div class="flex justify-between"><span class="text-slate-500">Nama</span><span class="font-semibold">{{ guestName || '—' }}</span></div><div class="flex justify-between"><span class="text-slate-500">Area</span><span class="font-semibold">{{ selectedZone?.name }}</span></div><div class="flex justify-between"><span class="text-slate-500">Tanggal</span><span class="font-semibold">{{ bookingDate }}</span></div><div class="flex justify-between"><span class="text-slate-500">Jam</span><span class="font-semibold">{{ selectedTime }}</span></div></div><div class="flex justify-between text-sm"><span class="text-slate-500">Total</span><b>{{ formatPrice(totalAmount) }}</b></div><div class="mt-2 flex justify-between text-sm"><span class="text-slate-500">Bayar sekarang</span><b>{{ formatPrice(amountToPay) }}</b></div><button type="button" :disabled="submitting" class="mt-7 flex w-full items-center justify-center gap-2 rounded-2xl bg-white px-5 py-4 text-sm font-bold text-slate-900" @click="submitBooking">{{ submitting ? 'Mengirim...' : 'Konfirmasi Booking' }} <ChevronRight class="size-4" /></button></div></aside></div></main>
</div>
</template>
